package dev.gbppimentel.snapcompanion;
import org.junit.*;
import static org.junit.Assert.*;
import java.nio.file.*;
import org.json.*;
public class GuideBookTest {
    private Catalog catalog;private GuideBook guide;
    static String asset(String name)throws Exception{return new String(Files.readAllBytes(Path.of("src/main/assets/"+name)),java.nio.charset.StandardCharsets.UTF_8);}
    @Before public void setup()throws Exception{catalog=new Catalog(asset("catalog.json"));guide=new GuideBook(asset("guidebook.json"),catalog);guide.apply(catalog);}
    @Test public void fullCoverageAndLegacyIdsSurvive(){assertEquals(936,guide.cues.size());assertEquals(234,catalog.requests.size());assertEquals(533,guide.encounters.size());assertTrue(catalog.hasRequest("hide-flowers"));for(Catalog.Course c:catalog.courses)assertFalse(c.id(),c.encounters().isEmpty());for(Catalog.Species s:catalog.species)for(int star=1;star<=4;star++)assertNotNull(s.name()+star,guide.cue(s.id(),star));}
    @Test public void unknownCoursePoseDoesNotBecomeVerifiedOrComplete(){Progress p=new Progress();String before;try{before=p.toJson();}catch(Exception e){throw new AssertionError(e);}ExpeditionPlanner.Plan plan=ExpeditionPlanner.build(catalog,guide,p,"park-day",3,0,1);assertFalse(plan.targets().isEmpty());assertTrue(plan.warnings().stream().anyMatch(s->s.contains("film remaining")));assertTrue(plan.estimatedLocations()>0);try{assertEquals(before,p.toJson());}catch(Exception e){throw new AssertionError(e);}}
    @Test public void incompatibleCourseCueCannotLeak(){Progress p=new Progress();p.objectives.add("810:2");var plan=ExpeditionPlanner.build(catalog,guide,p,"park-night",3,0,null);assertFalse(plan.targets().stream().anyMatch(t->t.id().equals("810:2")));}
    @Test public void skippedGoalsSurviveReplanningAndNotebookRoundTrip()throws Exception{Progress p=new Progress();p.notebook.skipped.add("810:1");p.notebook.tools.add("melody");p.notebook.requests.put("hide-flowers",Notebook.RequestState.ATTEMPTED);p.notebook.courses.put("park-day",new Notebook.CourseRecord(3,42000,19000));p.notebook.hints=Notebook.HintMode.ACTION;p.notebook.hintsConfigured=true;Progress copy=Progress.fromJson(p.toJson(),catalog);assertEquals(Notebook.RequestState.ATTEMPTED,copy.notebook.state("hide-flowers",copy.completedRequests));assertEquals(Notebook.HintMode.ACTION,copy.hintMode());assertFalse(ExpeditionPlanner.build(catalog,guide,copy,"park-day",3,0,null).targets().stream().anyMatch(t->t.id().equals("810:1")));assertEquals(p.notebook.json().toString(),p.copy().notebook.json().toString());}
    @Test public void invalidUpdateRejectedBeforeApplying()throws Exception{JSONObject data=new JSONObject(asset("guidebook.json"));data.getJSONArray("photoCues").remove(0);assertThrows(JSONException.class,()->new GuideBook(data.toString(),catalog));assertEquals(234,catalog.requests.size());}
    @Test public void ownedTablesCorrectAmbiguousRequestTargetsAndRetainCourseIdentity(){assertEquals(509,guide.variants.size());assertEquals(20,guide.forms(666).size());assertTrue(guide.matches(133,"evoli"));assertTrue(guide.matches(133,"イーブイ"));assertEquals(4,guide.forms(710).size());assertEquals(Integer.valueOf(3),guide.gameCourses.get("path-day"));assertEquals(Integer.valueOf(30),guide.gameCourses.get("camp"));assertEquals(3,catalog.requests.stream().filter(r->r.title().equals("Staredown for Venusaur")).findFirst().orElseThrow().pokemon());assertEquals(135,catalog.requests.stream().filter(r->r.title().equalsIgnoreCase("Fur Standing On End")).findFirst().orElseThrow().pokemon());}
    @Test public void optionalNotebookMigrationPreservesUnknownAccessAndKnownLocks()throws Exception{Progress p=new Progress();JSONObject old=p.notebook.json();old.remove("access");old.remove("story");old.remove("routes");Notebook legacy=Notebook.read(old,catalog);assertTrue(legacy.access.isEmpty());assertTrue(legacy.story.isEmpty());p.notebook.access.put("park-night",Notebook.Access.LOCKED);p.notebook.story.add("main-story-complete");p.notebook.routes.add("park-day:bidoof-dam");Progress restored=Progress.fromJson(p.toJson(),catalog);assertTrue(restored.notebook.story.contains("main-story-complete"));assertTrue(restored.notebook.routes.contains("park-day:bidoof-dam"));assertFalse(ExpeditionPlanner.rank(catalog,guide,restored).stream().anyMatch(r->r.plan().course().equals("park-night")));assertEquals("Cumulative research thresholds · Lv. 2: 40000 · Lv. 3: 110000 · MAX: 200000",guide.thresholdLabel("park-day"));}
}
